INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sovietski-proletariat-light-machine', 1, 'Palm Blaster: Laser (1 or 2)', '2D6 M.D. per blast', 1, '600 feet (183 m)', 'Each blast counts as one melee attack.', 'Effectively unlimited; tied to the cyborg''s nuclear power supply.', NULL, 'Optional; primary purpose defense. One or both palms, laser or ion. Police and military grade.'),
