  ('sovietski-proletariat-light-machine', 3, 'Concealed Forearm Vibro-Blade (1 or 2)', '2D4 M.D. per strike', 1, 'Melee; arm''s reach.', NULL, NULL, NULL, 'Optional; primary purpose close combat. A short silver-plated blade in each forearm, extended and retracted at will.'),
