-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sovietski-proletariat-light-machine', 'sovietski-heavy-machine-combat-cyborg');
SELECT 'their 17 locations are in' AS assertion, count(*) AS got, 17 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sovietski-proletariat-light-machine', 'sovietski-heavy-machine-combat-cyborg');
SELECT 'their 4 weapon entries are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sovietski-proletariat-light-machine', 'sovietski-heavy-machine-combat-cyborg');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sovietski-proletariat-light-machine', 'sovietski-heavy-machine-combat-cyborg') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

